function validate(input) {
  const [fn, args, restArgs] = input;
  const names = ['(...args) => args', '(a, b, c) => b + a - c', '(a, b) => a * b', '(...args) => args.length'];
  if (!names.includes(fn)) return `fn must be one of: ${names.map((name) => JSON.stringify(name)).join(', ')}.`;
  if (!Array.isArray(args) || args.length < 1 || args.length > 50000) return 'args must be a JSON array of 1 to 5 * 10^4 elements.';
  if (!Array.isArray(restArgs) || restArgs.length < 1 || restArgs.length > 50000) return 'restArgs must be a JSON array of 1 to 5 * 10^4 elements.';
  const placeholders = args.filter((arg) => arg === '_').length;
  if (placeholders > restArgs.length) return 'args has more "_" placeholders than restArgs has elements.';
  return null;
}

