function adapt(input, solve, kit) {
  const [name, args, restArgs] = input;
  const catalog = {
    '(...args) => args': (...values) => values,
    '(a, b, c) => b + a - c': (a, b, c) => b + a - c,
    '(a, b) => a * b': (a, b) => a * b,
    '(...args) => args.length': (...values) => values.length,
  };
  const show = (value) => { const text = JSON.stringify(value); return text !== undefined && text.length > 80 ? `${text.slice(0, 80)}...` : String(text); };
  const fn = (...values) => {
    const result = catalog[name](...values);
    kit.trace(`fn is called with ${show(values)} and returns ${show(result)}`);
    return result;
  };
  kit.trace(`partial(fn, ${show(args)}) is called, with fn = ${name}`);
  const partialFn = solve(fn, args);
  if (typeof partialFn !== 'function') throw new Error('partial must return a function.');
  kit.trace(`partialFn is called with the arguments ${show(restArgs)}`);
  const result = partialFn(...restArgs);
  kit.trace(`partialFn returns ${show(result)}`);
  return result;
}

