function partial(fn, args) {
  // Take the rest arguments off the front of a queue, then append whatever is left.
  return (...restArgs) => {
    const queue = restArgs.slice();
    const filled = args.map((arg) => (arg === '_' ? queue.shift() : arg));
    return fn.apply(null, filled.concat(queue));
  };
}

