function generate(rand, size) {
  const names = ['(...args) => args', '(a, b, c) => b + a - c', '(a, b) => a * b', '(...args) => args.length'];
  const fn = names[Math.floor(rand() * names.length)];
  const numeric = fn === '(a, b, c) => b + a - c' || fn === '(a, b) => a * b';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const value = () => {
    if (numeric || size === 'large') return Math.floor(rand() * 41) - 20;
    return pick([0, 1, -3, 7, 'x', '_', '__', '', null, true, false, [1, '_'], { k: 2 }]);
  };
  const restLength = size === 'small' ? 1 + Math.floor(rand() * 4) : 1000 + Math.floor(rand() * 1001);
  const argsLength = size === 'small' ? 1 + Math.floor(rand() * 5) : 1000 + Math.floor(rand() * 1001);
  const restArgs = Array.from({ length: restLength }, value);
  let placeholders = Math.floor(rand() * (Math.min(restLength, argsLength) + 1));
  const args = [];
  for (let i = 0; i < argsLength; i++) {
    // Spread the placeholders over the slots that remain.
    if (placeholders > 0 && rand() * (argsLength - i) < placeholders) {
      args.push('_');
      placeholders--;
    } else {
      let arg = value();
      while (arg === '_') arg = value();
      args.push(arg);
    }
  }
  return [fn, args, restArgs];
}
